MIN_VOTES = 2

# Physics/window priors (data is clearly event-centered near sample ~6000):
# - Restrict picks to a plausible event window
# - Enforce P < S at same station, with realistic S-P separation for local events
EVENT_WIN = (3000, 9000)       # discard picks outside this window
MIN_SP_GAP = 20                # 0.2 s
MAX_SP_GAP = 800               # 8 s (~ up to ~60 km distance)

def cluster_and_score(plist):
    """Cluster picks within MERGE_TOL and return list of (best_idx, best_prob, n_votes)."""
    if not plist:
        return []
    plist = sorted(plist)
    clusters = [[plist[0]]]
    for item in plist[1:]:
        if item[0] - clusters[-1][-1][0] <= MERGE_TOL:
            clusters[-1].append(item)
        else:
            clusters.append([item])
    out = []
    for cluster in clusters:
        distinct_models = {c[2] for c in cluster}
        best = max(cluster, key=lambda x: x[1])
        out.append((best[0], best[1], len(distinct_models)))
    return out

for i, path in enumerate(files):
    fname = os.path.basename(path)
    stream, t0, dt = load_stream(path)

    all_picks = {"P": [], "S": []}
    for name, m in models:
        try:
            picks = m.classify(stream, P_threshold=P_THR, S_threshold=S_THR).picks
        except Exception as e:
            print(f"Error on {fname} with {name}: {e}")
            continue
        for p in picks:
            idx = int(round((p.peak_time - t0) / dt))
            if idx < 0 or idx >= 12000:
                continue
            if idx < EVENT_WIN[0] or idx > EVENT_WIN[1]:
                continue
            prob = float(getattr(p, "peak_value", 1.0) or 1.0)
            if p.phase in all_picks:
                all_picks[p.phase].append((idx, prob, name))

    p_cands = cluster_and_score(all_picks["P"])
    s_cands = cluster_and_score(all_picks["S"])

    def accept(cand):
        idx, prob, votes = cand
        return votes >= MIN_VOTES or prob >= 0.5

    p_cands = [c for c in p_cands if accept(c)]
    s_cands = [c for c in s_cands if accept(c)]

    # S: pick single best (highest score = votes*prob) — S is the more reliable anchor
    s_best = None
    if s_cands:
        s_best = max(s_cands, key=lambda c: (c[2], c[1]))
        rows.append((fname, "S", s_best[0]))

    # P: constrain to be plausibly before S with realistic S-P gap.
    # If we have S: keep P candidates in [S - MAX_SP_GAP, S - MIN_SP_GAP], choose best.
    # If no S: allow one high-confidence P candidate.
    if p_cands:
        if s_best is not None:
            s_idx = s_best[0]
            valid = [c for c in p_cands
                     if s_idx - MAX_SP_GAP <= c[0] <= s_idx - MIN_SP_GAP]
            if valid:
                pbest = max(valid, key=lambda c: (c[2], c[1]))
                rows.append((fname, "P", pbest[0]))
        else:
            # No S anchor: only keep the single strongest P.
            pbest = max(p_cands, key=lambda c: (c[2], c[1]))
            if pbest[2] >= MIN_VOTES or pbest[1] >= 0.5:
                rows.append((fname, "P", pbest[0]))

    if (i + 1) % 20 == 0:
        print(f"  done {i+1}/{len(files)}, picks so far: {len(rows)}")"}: Editing /root/pick.py
